from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_balanced(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    paren_string = paren_string.replace(" ", "")
    result = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count = 1
            while count != 0:
                i += 1
                if paren_string[i] == '(':
                    count += 1
                elif paren_string[i] == ')':
                    count -= 1
            result.append(paren_string[start:i+1])
            start = i + 1

    return [group for group in result if is_balanced(group)]

